solve:{[tokens;codes]
  norm:{[x] t:"J"$x; $[1000000000<=abs t;0j;t]};
  float:{[x] t:"F"$x; $[1000000f<=abs t;0f;0.001*floor[0.5+1000f*t]*0.001f]};
  boolean:{[x]
    l:lower x;
    $[l="1"|l="t"|l="true";1;
      $[l="0"|l="f"|l="false";0;0]]};
  ch:{[x] "J"$enlist first x};
  sym:{x};
  effective:"";longs:();floats:();bools:();chars:();syms:();symIdx:();recast:0;
  i:0;while[i<count tokens;
    tok:tokens i;decl:codes i;effectivecode:"";value:0f;
    attempt:"";attempt:attempt,decl;
    if[not attempt~"j";attempt:attempt,"j"];
    if[not attempt~"f";attempt:attempt,"f"];
    if[not attempt~"b";attempt:attempt,"b"];
    if[not attempt~"c";attempt:attempt,"c"];
    if[not attempt~"s";attempt:attempt,"s"];
    j:0;while[j<count attempt;
      code:attempt j;
      if[code="j";
        if[0=count tok;]:
        if[not first tok in "0123456789-";]:
        if[1=count tok;if[not tok~"-";]:];
        if[10=count tok;if[not ("-"=first tok)&((("1"=string first 9 tok)&((("0"=string last 8 tok)|("0"=string first 8 tok))&("0"=string last 7 tok)));]:];
        effectivecode:"j";value:norm tok;break];
      if[code="f";
        if[0=count tok;]:
        if[not first tok in "0123456789.-";]:
        effectivecode:"f";value:float tok;break];
      if[code="b";effectivecode:"b";value:boolean tok;break];
      if[code="c";if[1=count tok;effectivecode:"c";value:ch tok;break]];
      if[code="s";effectivecode:"s";value:sym tok;break];
      j+:1];
    effective:effective,effectivecode;
    if[effectivecode="j";longs,:value];
    if[effectivecode="f";floats,:value];
    if[effectivecode="b";bools,:value];
    if[effectivecode="c";chars,:value];
    if[effectivecode="s";
      idx:$[tok in syms;first where syms=tok;count syms];
      if[idx=count syms;syms,:enlist tok];
      symIdx,:idx];
    if[effectivecode<>decl;recast+:1];
    i+:1];
  total:(sum longs)+(sum floats)+(sum bools)+(sum chars)+(sum symIdx);
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (effective;longs;floats;bools;chars;syms;symIdx;recast;total)}
